select distinct
	t2.dt_month
into #DML_销售收入与成本_OPTION_DTMONTH_DAF4
from #DML_OPTION_DTMONTH t1
left join DML_CALENDAR t2
	on t2.dt_month between datefromparts(year(cast(t1.dt_month as date)), 1, 1) and t1.dt_month;

create unique clustered index idx__dm
	on #DML_销售收入与成本_OPTION_DTMONTH_DAF4
	   (dt_month);

/** DML_销售收入与成本_BY_DM_地_B46981BE { pk(dt_month, [地区]) }  **/
