	dt_month,
	region as [地区],
	SUM(revenue_amount) as [净收入],
	SUM(cost_amount) as [销售成本]
from TABLE_PROFITABILITY
where dt_month in (select dt_month from #DML_销售收入与成本_OPTION_DTMONTH_DAF4 [#dml_销售收入与成本_option_dtmonth_daf4])
group by dt_month,
	region
)

/** MAIN_QUERY { pk(dt_month, [地区]) } **/
select
	/** auto-generated by datoml: qfb35fd2779 **/
	t2.[地区],
	t1.dt_month,
	((SUM(t2.[净收入])) - (SUM(t2.[销售成本]))) / nullif((SUM(t2.[净收入])), 0) as [本年累计毛利率]
from #DML_OPTION_DTMONTH t1
inner join DML_销售收入与成本_BY_DM_地_B46981BE t2
	on t2.dt_month between datefromparts(year(cast(t1.dt_month as date)), 1, 1) and t1.dt_month
