if object_id(N'tempdb..[#DML_销售收入与成本_BY_DM_地_30F381B_YTD]', N'U') is not null drop table [#DML_销售收入与成本_BY_DM_地_30F381B_YTD];
select
    t1.dt_month,
    t2.地区,
    SUM(t2.净收入) as 净收入,
    SUM(t2.销售成本) as 销售成本,
    (SUM(t2.净收入) - SUM(t2.销售成本)) / nullif(SUM(t2.净收入), 0) as 本年累计毛利率
