from #DML_OPTION_DTMONTH t1
inner join [#DML_销售收入与成本_BY_DM_地_B46981BE] t2
    on t2.dt_month between datefromparts(year(cast(t1.dt_month as date)), 1, 1) and t1.dt_month
group by t1.dt_month, t2.地区;

create unique clustered index idx__dm_地
	on [#DML_销售收入与成本_BY_DM_地_30F381B_YTD]
	   (dt_month, 地区);

/** [#DML_销售收入与成本_BY_DM_地_4EA881B_YTD_YA] { pk(dt_month, 地区) } **/
if object_id(N'tempdb..[#DML_销售收入与成本_BY_DM_地_4EA881B_YTD_YA]', N'U') is not null drop table [#DML_销售收入与成本_BY_DM_地_4EA881B_YTD_YA];
select
    t1.dt_month,
    t2.地区,
    SUM(t2.净收入) as 净收入,
    SUM(t2.销售成本) as 销售成本,
    (SUM(t2.净收入) - SUM(t2.销售成本)) / nullif(SUM(t2.净收入), 0) as 上年同期累计毛利率
into [#DML_销售收入与成本_BY_DM_地_4EA881B_YTD_YA]
from #DML_OPTION_DTMONTH t1
inner join [#DML_销售收入与成本_BY_DM_地_B46981BE] t2
    on t2.dt_month between dateadd(year, -1, cast(datefromparts(year(cast(t1.dt_month as date)), 1, 1) as date)) and dateadd(year, -1, cast(t1.dt_month as date))
group by t1.dt_month, t2.地区;

create unique clustered index idx__dm_地
	on [#DML_销售收入与成本_BY_DM_地_4EA881B_YTD_YA]
	   (dt_month, 地区);

/** DML_销售收入与成本_BY_DM_地_68B181B { pk(dt_month, 地区) } **/
with DML_销售收入与成本_BY_DM_地_68B181B as (
select
    coalesce(t1.dt_month, t2.dt_month) as dt_month,
    coalesce(t1.地区, t2.地区) as 地区,
    100 * (t1.本年累计毛利率 - t2.上年同期累计毛利率) as 毛利率变动百分点
from [#DML_销售收入与成本_BY_DM_地_30F381B_YTD] t1
full outer join [#DML_销售收入与成本_BY_DM_地_4EA881B_YTD_YA] t2
    on (t2.dt_month = t1.dt_month or (t2.dt_month is null and t1.dt_month is null))
    and (t2.地区 = t1.地区 or (t2.地区 is null and t1.地区 is null))
)


