/**                       query                       **/
/*-----------------------------------------------------*/

select
    t.地区,
    t.dt_month,
    t3b47f.本年累计毛利率,
    t62d1a.上年同期累计毛利率,
    t.毛利率变动百分点
from DML_销售收入与成本_BY_DM_地_68B181B t
left join [#DML_销售收入与成本_BY_DM_地_30F381B_YTD] t3b47f 
	on (t3b47f.dt_month = t.dt_month or (t3b47f.dt_month is null and t.dt_month is null))
	and (t3b47f.地区 = t.地区 or (t3b47f.地区 is null and t.地区 is null))
left join [#DML_销售收入与成本_BY_DM_地_4EA881B_YTD_YA] t62d1a 
	on (t62d1a.dt_month = t.dt_month or (t62d1a.dt_month is null and t.dt_month is null))
	and (t62d1a.地区 = t.地区 or (t62d1a.地区 is null and t.地区 is null))
order by t.地区, t.dt_month;
